"use client";

import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { oxFace, oxFaceHover, destructiveFace, focusRing, pillFace, pressScale, quietFace } from "./_shared";

/**
 * Margin IconButton: one glyph on the same faces as the Button.
 *
 * The default is the ruled toolbar tab, `primary` is the oxblood face and
 * `ghost` is the quiet choice for a toolbar. The square shape keeps a corner
 * that grows with the button; `circle` makes it round.
 */
const iconButtonVariants = cva(
  [
    "relative inline-flex shrink-0 select-none items-center justify-center",
    pressScale,
    focusRing,
    "disabled:pointer-events-none disabled:opacity-50",
    "data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
    "[&_svg]:pointer-events-none [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        default: cn(pillFace, "aria-expanded:bg-(--field)"),
        primary: cn(oxFace, oxFaceHover),
        secondary: quietFace,
        ghost: "bg-transparent text-muted-foreground hover:bg-accent hover:text-foreground",
        destructive: destructiveFace,
        outline: "bg-transparent text-foreground shadow-(--pill-edge) hover:bg-accent",
      },
      size: {
        xs: "size-6 rounded-md [&_svg]:size-3.5",
        sm: "size-7 rounded-lg [&_svg]:size-4",
        default: "size-7.5 rounded-lg [&_svg]:size-4",
        lg: "size-9 rounded-lg [&_svg]:size-4.5",
        xl: "size-10 rounded-xl [&_svg]:size-5",
      },
      corners: {
        square: "",
        circle: "rounded-full",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
      corners: "square",
    },
  },
);

/** Props for the IconButton; give it an `aria-label`, since the glyph carries no text. */
export interface IconButtonProps
  extends
    Omit<ButtonPrimitive.Props, "className">,
    VariantProps<typeof iconButtonVariants> {
  className?: string;
}

const IconButton = React.forwardRef<HTMLButtonElement, IconButtonProps>(
  ({ className, variant, size, corners, ...props }, ref) => (
    <ButtonPrimitive
      ref={ref}
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant, size, corners, className }))}
      {...props}
    />
  ),
);
IconButton.displayName = "IconButton";

export { IconButton, iconButtonVariants };
